$$
 egin{aligned}{w}^{′}(x) & ={({e}^{2x})}^{′}\cdot \operatorname{artanh}⁡x+{e}^{2x}\cdot {(\operatorname{artanh}⁡x)}^{′} \  & =2{e}^{2x}\cdot \operatorname{artanh}⁡x+{e}^{2x}\cdot  rac{1}{1-{x}^{2}} \  & =2{e}^{2x}\operatorname{artanh}⁡x+{{ rac{{e}^{2x}}{1-{x}^{2}}}_{⏟}}_{y(x)}\end{aligned}
